<?php require_once __DIR__.'/../includes/functions.php';require_once __DIR__.'/../includes/data_insert.php';require_admin();verify_csrf();if(empty($_SESSION['pending_extraction']))flash_redirect('admin/smart_upload.php','error','The extraction session expired. Please upload the file again.');$pdo=db();$inserted=0;$skipped=0;$used=[];try{$pdo->beginTransaction();foreach($_POST['rankings']??[] as $r)if(isset($r['include'])){insert_ranking($r)?($inserted++):($skipped++);$used['rankings']=true;}foreach($_POST['breakdowns']??[] as $r)if(isset($r['include'])){insert_breakdown($r)?($inserted++):($skipped++);$used['ranking_breakdowns']=true;}foreach($_POST['colleges']??[] as $r)if(isset($r['include'])){insert_college($r)?($inserted++):($skipped++);$used['colleges']=true;}foreach($_POST['programs']??[] as $r)if(isset($r['include'])){insert_program($r)?($inserted++):($skipped++);$used['programs']=true;}foreach($_POST['accreditations']??[] as $r)if(isset($r['include'])){insert_accreditation($r)?($inserted++):($skipped++);$used['accreditations']=true;}$type=count($used)===1?array_key_first($used):(count($used)>1?'mixed':'none');$pdo->prepare('INSERT INTO uploads_log(uploaded_by,filename,file_type,upload_type,rows_inserted) VALUES(?,?,?,?,?)')->execute([$_SESSION['user_id'],$_SESSION['pending_extraction_filename']??'unknown',$_POST['file_type']??($_SESSION['pending_extraction_file_type']??''),$type,$inserted]);$pdo->commit();}catch(Throwable $e){$pdo->rollBack();flash_redirect('admin/review_extraction.php','error','Could not save the reviewed extraction: '.$e->getMessage());}unset($_SESSION['pending_extraction'],$_SESSION['pending_extraction_filename'],$_SESSION['pending_extraction_file_type']);$msg="Saved {$inserted} row(s).".($skipped?" {$skipped} row(s) skipped.":'');flash_redirect('admin/dashboard.php','success',$msg);
